S={}
for line in RAW.strip().splitlines():
    p=line.split('|'); route=p[0]
    cards=[]
    for x in p[3:6]: cards.append(tuple(x.split('~',1)))
    S[route]={'title':p[1],'lead':p[2],'cards':cards,'steps':p[6].split('~'),'trust':p[7],'contact':p[8]}
STYLE='''<style data-stage52="true">.s52{padding:5.5rem 0}.s52-head{display:grid;grid-template-columns:.34fr 1.66fr;gap:2rem;margin-bottom:2rem}.s52-head>span{color:#737c86;font:700 .65rem/1.4 ui-monospace,monospace;letter-spacing:.08em}.s52 h2{margin:0;font-size:clamp(2.35rem,5vw,4.7rem);line-height:.98;letter-spacing:-.052em;max-width:16ch}.s52-head p,.s52-card p{color:#929aa4}.s52-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.7rem}.s52-card{border:1px solid var(--line);border-radius:1.05rem;padding:1.2rem;background:linear-gradient(145deg,#11151a,#0d1014)}.s52-card h3{margin:.3rem 0 0}.s52-card p{font-size:.86rem;line-height:1.65}@media(max-width:900px){.s52-head{grid-template-columns:1fr}.s52-grid{grid-template-columns:1fr 1fr}}@media(max-width:620px){.s52{padding:4.2rem 0}.s52-grid{grid-template-columns:1fr}.s52 h2{max-width:100%}}</style>'''
def block(c):
    cards=''.join(f'<article class="s52-card"><h3>{html.escape(t)}</h3><p>{html.escape(d)}</p></article>' for t,d in c['cards'])
    return f'<section class="s52" data-stage52-boundary="true"><div class="container"><div class="s52-head"><span>04 / ГРАНИЦА</span><div><h2>{html.escape(c["title"])}</h2><p>{html.escape(c["lead"])}</p></div></div><div class="s52-grid">{cards}</div></div></section>'
for route,c in S.items():
    p=root/route/'index.html'; t=p.read_text(encoding='utf8')
    for x in REMOVE:t=t.replace(x,'')
    for old,new in zip(OLD_STEPS,c['steps']):t=t.replace(old,new)
    t=t.replace(OLD_TRUST,c['trust']).replace(OLD_CONTACT,c['contact'])
    if 'data-stage52-boundary' not in t:
        marker='<section class="s48-section" aria-labelledby="s48-budget-title">'; i=t.find(marker)
        if i<0:raise SystemExit('stage52 budget marker missing '+route)
        t=t[:i]+block(c)+t[i:]
    if 'data-stage52="true"' not in t:t=t.replace('</head>',STYLE+'</head>',1)
    p.write_text(t,encoding='utf8')
TITLE={
'services':'Услуги разработки: сайты, приложения, Telegram и CRM | Alexuys',
'freelance-developer':'Фриланс-разработчик сайтов, приложений и ботов | Alexuys',
'about':'Александр — разработчик цифровых продуктов | Alexuys',
'backend-development':'Backend-разработка на заказ — API и данные | Alexuys',
'python-development':'Python-разработка — backend и автоматизация | Alexuys',
'api-integrations':'API-интеграции — CRM, платежи и Telegram | Alexuys'}
for route,title in TITLE.items():
    p=root/route/'index.html'; t=p.read_text(encoding='utf8'); e=html.escape(title,quote=True)
    t=re.sub(r'<title>.*?</title>',f'<title>{e}</title>',t,count=1,flags=re.S)
    for attr,key in [('property','og:title'),('name','twitter:title')]:
        q=re.compile(rf'(<meta\s+content=")[^"]*("\s+{attr}="{re.escape(key)}"\s*/?>)',re.I);t=q.sub(lambda m:m.group(1)+e+m.group(2),t,count=1)
    p.write_text(t,encoding='utf8')
after=hashlib.sha256(home.read_bytes()).hexdigest()
if before!=after:raise SystemExit('stage52 invariant failed: homepage changed')
print('stage52: differentiated',len(S),'service pages; homepage unchanged')
